import { atom, read, update } from 'claude-code'
import type { Register, BoxProps, ElementConstructor, EngineInterface, RenderElement, RenderNode, SessionRateLimit, Timer } from 'claude-code'

import type { Limit } from '../types'

// Reset countdowns read in minutes, so a 30s tick keeps them honest.
const TICK_MS = 30_000
const LABELS: Record<string, string> = { five_hour: '5h', seven_day: '7d', spend_limit: 'spend' }

const usage = atom({ plugin: 'usage-limits', key: 'usage' } as const, { limits: [] })
const now = atom({ plugin: 'usage-limits', key: 'now' } as const, 0)
const shownPct = atom({ plugin: 'usage-limits', key: 'shownPct' } as const, 0)

// The bar eases toward a new value over a few frames instead of jumping.
const GROW_MS = 40
let grower: Timer | undefined
const grow = async ($: EngineInterface, target: number) => {
  grower?.cancel()
  grower = $.clock.every(GROW_MS, async () => {
    const shown = await read($, shownPct)
    const step = Math.sign(target - shown) * Math.max(0.5, Math.abs(target - shown) / 5)
    const nextPct = Math.abs(target - shown) <= 0.5 ? target : shown + step
    await update($, shownPct, () => nextPct)
    if (nextPct === target) grower?.cancel()
  })
}

const toLimits = (limits: SessionRateLimit[]): Limit[] => limits.map(({ kind, percentUsed, resetsAt }) => ({ kind, percentUsed, resetsAt }))

// Limits of the last session that saw any, so a new one shows them before its first response reports. They are marked stale
// (other sessions may have used the window since), and a window that has reset since shows its placeholder.
const seed = async ($: EngineInterface) => {
  const saved = await $.store.get('limits').catch(() => undefined)
  if (!Array.isArray(saved)) return
  const t = Date.now()
  const limits = (saved as Limit[]).map(l => (!l.resetsAt || Date.parse(l.resetsAt) > t ? { ...l, isStale: true } : { kind: l.kind, isStale: true }))
  await update($, usage, u => (u.limits.length ? u : { ...u, limits }))
}

// An engine reading with no limits (a fresh session) keeps the stale ones shown; a live reading replaces them.
const apply = async ($: EngineInterface, percent: number | undefined, limits: SessionRateLimit[]) => {
  const live = toLimits(limits)
  await update($, usage, u => ({ contextPercent: percent, limits: live.length ? live : u.limits.filter(l => l.isStale) }))
  if (percent !== undefined) await grow($, percent)
  if (live.length) await $.store.set('limits', live).catch(() => undefined)
}

// "6d 18h" past a day, "2h 5m" past an hour, else "27m".
const span = (ms: number) => {
  const m = Math.max(0, Math.round(ms / 60_000))
  const [d, h] = [Math.floor(m / 1440), Math.floor((m % 1440) / 60)]
  return d ? `${d}d ${h}h` : h ? `${h}h ${m % 60}m` : `${m}m`
}

// Every modz mod places its tile in one shared band: a lead column (the bot), then a column of tiles, then an optional
// right column. A column with no tiles is not drawn, and columns wrap under each other when the width runs out.
const BAND = 'modz-band'
const SLOTS: Record<string, 'lead' | 'left' | 'right'> = {
  buddy: 'lead',
  'usage-limits': 'left',
  'cache-timer': 'left',
  'model-info': 'left',
  orchestrator: 'left',
}
const ORDER = Object.keys(SLOTS)
const keyOf = (n: RenderNode) => (typeof n !== 'string' && n.type === 'Box' ? String(n.props?.key ?? '') : '')
const rank = (n: RenderNode) => {
  const i = ORDER.indexOf(keyOf(n))
  return i < 0 ? ORDER.length : i
}
const pack = (Box: ElementConstructor<BoxProps>, below: RenderElement, tile: RenderElement) => {
  const isEmpty = below.type === 'Box' && !below.children?.length
  const tiles = keyOf(below) === BAND
    ? (below.type === 'Box' ? below.children ?? [] : []).flatMap(col => (typeof col !== 'string' && col.type === 'Box' ? col.children ?? [] : [col]))
    : isEmpty ? [] : [below]
  const all = [...tiles, tile].sort((a, b) => rank(a) - rank(b))
  const [lead, left, right] = (['lead', 'left', 'right'] as const).map(slot => all.filter(n => (SLOTS[keyOf(n)] ?? 'left') === slot))
  return (
    <Box key={BAND} flexDirection="row" flexWrap="wrap" columnGap={3}>
      {lead!.length > 0 && <Box key="modz-lead" flexDirection="column" justifyContent="center">{lead}</Box>}
      {left!.length > 0 && <Box key="modz-left" flexDirection="column" flexGrow={right!.length > 0 ? 1 : 0}>{left}</Box>}
      {right!.length > 0 && <Box key="modz-right" flexDirection="column" alignItems="flex-end">{right}</Box>}
    </Box>
  )
}

// Each tile has its own Claude theme color; values turn yellow at 60% and red at 85% as they fill.
const TINT = 'claude'
const tone = (pct: number, calm: string) => (pct >= 85 ? 'error' : pct >= 60 ? 'warning' : calm)

// The session binds around session.start, so the first read waits for next(e); one that still rejects is retried on the tick.
// Every reload clears isLoaded first, so a failed one is retried the same way.
let isLoaded = false
// A resumed session has no live window until its first response, so the last response's size from classic.SessionStart stands in;
// that count includes the output, so it reads a hair above the status line's own figure. A session with no prompts is 0% full.
let resumedTokens: number | undefined
const load = async ($: EngineInterface) => {
  try {
    const [u, turns] = await Promise.all([$.session.usage(), $.session.turns().catch(() => undefined)])
    const { percent, window } = u.context
    const seeded = resumedTokens && window ? Math.min(100, Math.round((resumedTokens / window) * 100)) : undefined
    await apply($, percent ?? seeded ?? (turns === 0 && window ? 0 : undefined), u.rateLimits)
    isLoaded = true
  } catch (err) {
    $.ui.log(`usage-limits: ${err}`, { to: 'debug' })
  }
}

const reload = ($: EngineInterface) => {
  isLoaded = false
  return load($)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await update($, now, () => Date.now())
    $.clock.every(TICK_MS, () => {
      void update($, now, () => Date.now())
      if (!isLoaded) void load($)
    })
    await seed($)
    await load($)
    return started
  })

  // /clear and a resume end the session before the next one binds, so the tile resets and the tick loads it.
  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear' || e.reason === 'resume') {
      isLoaded = false
      resumedTokens = undefined
      await update($, usage, () => ({ limits: [] }))
      await seed($)
    }
    return next(e)
  })

  on('session.compact', async ($, e, next) => {
    const compacted = await next(e)
    if (e.trigger !== 'precompute' && e.agentId === undefined && !compacted.skip) await reload($)
    return compacted
  }).catch(($, e, next) => next(e))

  // Loads right after /clear, resume and compact where the engine runs classic hooks; not where an organization manages Claude Code.
  on('classic.SessionStart', async ($, e, next) => {
    const started = await next(e)
    resumedTokens = e.source === 'resume' || e.source === 'fork' ? e.context_tokens : undefined
    await reload($)
    return started
  }).catch(($, e, next) => next(e))

  on('session.measure', async ($, e, next) => {
    await apply($, e.context.percent, e.rateLimits)
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const below = await next(e)
    if (e.props.hasSurvey) return below
    const { Box, Text } = $.ui.resolve(e)
    const [u, , shown] = await Promise.all([read($, usage), read($, now), read($, shownPct)])
    const t = Date.now()
    const pct = u.contextPercent

    const width = Math.max(5, Math.min(10, Math.floor(e.props.bodyColumns / 12)))
    const filled = pct === undefined ? 0 : Math.min(width, Math.max(0, Math.round((shown / 100) * width)))
    const metric = (label: string, value?: number, detail?: string, isStale?: boolean) => (
      <Text>
        <Text dimColor>{label} </Text>
        {value === undefined ? <Text dimColor>–</Text> : isStale ? <Text dimColor>~{Math.round(value)}%</Text> : <Text bold color={tone(value, 'success')}>{Math.round(value)}%</Text>}
        {detail && <Text dimColor> · {detail}</Text>}
      </Text>
    )

    return pack(Box, below, (
      <Box key="usage-limits" flexDirection="row" flexWrap="wrap" columnGap={3}>
        <Text>
          <Text color={TINT}>{'ctx'.padEnd(5)} </Text>
          <Text color={tone(pct ?? 0, TINT)}>{'█'.repeat(filled)}</Text>
          <Text dimColor>{'░'.repeat(width - filled)} </Text>
          {pct === undefined ? <Text dimColor>–</Text> : <Text bold color={tone(pct, TINT)}>{Math.round(pct)}%</Text>}
        </Text>
        {u.limits.length > 0
          ? u.limits.map(l => metric(LABELS[l.kind] ?? l.kind, l.percentUsed, l.resetsAt && span(Date.parse(l.resetsAt) - t), l.isStale))
          : [metric('5h'), metric('7d')]}
      </Box>
    ))
  })
}

